package dev.recipeeditor.exporters;

import dev.recipeeditor.recipeengine.editor.*;
import java.util.*;
public final class CraftTweakerRecipeExporter implements RecipeExporter {
    @Override public ExportFormat format(){return ExportFormat.CRAFTTWEAKER;}
    private String manager(final String serializer){return switch(serializer){case "minecraft:crafting_shaped","minecraft:crafting_shapeless"->"minecraft:crafting";case "minecraft:smithing_transform","minecraft:smithing_trim"->"minecraft:smithing";default->serializer;};}
    @Override public ExportCapability checkCapability(final RecipeChange change,final ExportContext context) {
        if(!context.modVersion("crafttweaker").equals("14.0.57"))return ExportCapability.unsupported("CraftTweaker API is pinned to 14.0.57 for Forge 1.20.1; installed="+context.modVersion("crafttweaker"));
        final String error=new VanillaExportSupport().check(change,context);if(!error.isEmpty())return ExportCapability.unsupported(error);
        if(change.type()!=RecipeChangeType.DELETE&&!change.id().namespace().equals("crafttweaker"))return ExportCapability.unsupported("CraftTweaker addJsonRecipe creates IDs in crafttweaker namespace. Arbitrary namespace cannot be preserved; use Datapack/KubeJS.");
        if(change.type()==RecipeChangeType.UPDATE && context.originals().findById(change.id()).stream().anyMatch(r->!manager(r.type().displayId()).equals(manager(change.replacement().getFirst().type().displayId()))))return ExportCapability.unsupported("Changing CraftTweaker recipe managers during UPDATE is not verified");
        final var managers=context.definitions(change).stream().map(recipe->manager(recipe.type().displayId())).distinct().toList();if(managers.size()!=1)return ExportCapability.unsupported("Ambiguous original recipe managers");
        try{if(change.type()!=RecipeChangeType.DELETE)new ZenScriptGenerator().data(change.replacement().getFirst().rawJson());}
        catch(IllegalArgumentException invalid){return ExportCapability.unsupported(invalid.getMessage());}
        return ExportCapability.supported("Verified Vanilla recipe manager addJsonRecipe/removeByName. CREATE/UPDATE preserve only crafttweaker IDs; DELETE accepts full ID.");
    }
    @Override public Map<String,String> generate(final List<RecipeChange> changes,final ExportContext context) {
        if(changes.isEmpty())return Map.of();final var script=new StringBuilder("// Generated by Minecraft Recipe Editor. Runtime validation required.\nimport crafttweaker.api.data.MapData;\n\n");final var text=new ExportText();
        for(final var change:changes.stream().sorted(Comparator.comparing(c->c.id().toString())).toList()) {
            if(!checkCapability(change,context).supported())throw new IllegalArgumentException("Unsupported CraftTweaker operation");
            final String manager="<recipetype:"+manager(context.definitions(change).getFirst().type().displayId())+">";
            if(change.type()!=RecipeChangeType.CREATE)script.append(manager).append(".removeByName(").append(text.quote(change.id().toString())).append(");\n");
            if(change.type()!=RecipeChangeType.DELETE)script.append(manager).append(".addJsonRecipe(").append(text.quote(change.id().path())).append(", ").append(new ZenScriptGenerator().data(change.replacement().getFirst().rawJson())).append(" as MapData);\n");
        }
        return Map.of("scripts/recipe_editor_"+context.profile().id()+"_generated.zs",script.toString());
    }
}
